/* New and existing tasks share a top navigation bar. Fields stay in their original form. */
(()=>{'use strict';if(!document.body.classList.contains('shared-app'))return;const previous=createTaskForm;createTaskForm=function(...args){const result=previous(...args),form=document.querySelector('#newSharedTask'),dialog=document.querySelector('#sharedDialog'),head=document.querySelector('#sharedDetail .shared-task-head');if(!form||!head)return result;dialog.classList.add('task-focus-layout','task-structured');const nav=document.createElement('div');nav.className='task-focus-nav';nav.setAttribute('role','tablist');nav.setAttribute('aria-label','بخش‌های کار جدید');head.after(nav);const general=document.createElement('section'),files=document.createElement('section'),history=document.createElement('section');general.className=files.className=history.className='task-focus-panel';const submit=form.querySelector('button.primary');const attachments=form.querySelector('.creation-attachments');[...form.childNodes].forEach(n=>{if(n!==submit&&n!==attachments)general.append(n)});if(attachments)files.append(attachments);const description=general.querySelector('textarea[name=description]')?.closest('label');if(description){history.append(description);description.querySelector('textarea').placeholder='توضیحات و نکات مربوط به این کار را بنویسید…';}history.insertAdjacentHTML('beforeend','<p class="shared-meta">این توضیحات همراه با کار ذخیره می‌شود.</p>');const panels=[general,files,history],titles=['مشخصات و ارجاع','فایل‌ها و نسخه‌ها','توضیحات'];const buttons=[];function select(index){panels.forEach((p,i)=>{p.hidden=i!==index;buttons[i].setAttribute('aria-selected',String(i===index));buttons[i].tabIndex=i===index?0:-1})}panels.forEach((p,i)=>{p.setAttribute('role','tabpanel');p.id='new-task-panel-'+i;const b=document.createElement('button');b.type='button';b.textContent=titles[i];b.id='new-task-tab-'+i;b.setAttribute('role','tab');b.setAttribute('aria-controls',p.id);p.setAttribute('aria-labelledby',b.id);b.onclick=()=>select(i);b.onkeydown=e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const n=(i+(e.key==='ArrowLeft'?1:2))%3;select(n);buttons[n].focus()};buttons.push(b);nav.append(b);form.insertBefore(p,submit)});select(0);form.addEventListener('invalid',e=>{const index=panels.findIndex(p=>p.contains(e.target));if(index>=0)select(index)},true);const root=document.querySelector('#sharedDetail'),top=document.createElement('div'),body=document.createElement('div');top.className='task-dialog-top';body.className='task-dialog-body';top.append(head,nav);body.append(form);root.replaceChildren(top,body);dialog.addEventListener('close',()=>dialog.classList.remove('task-focus-layout','task-structured'),{once:true});return result};})();
